apiVersion: apps/v1
kind: Deployment
metadata:
  name: vuoro-control
  namespace: vuoro-system
spec:
  replicas: 1
  selector:
    matchLabels: {app.kubernetes.io/name: vuoro-control}
  template:
    metadata:
      labels: {app.kubernetes.io/name: vuoro-control}
      annotations:
        # sha256 of platform/runtime-secrets/oauth-clients.secret.yaml (the SOPS
        # file, not the plaintext): control reads clients.json once at startup,
        # so a changed clients file must roll the pod (credential-rotation.md).
        checksum/vuoro-oauth-clients: 9dd630981954552adea39a227463ae10198e71116a1e26b6d01901967c259ddf  # gitleaks:allow (sha256 of the encrypted file, not a secret)
    spec:
      serviceAccountName: vuoro-control
      automountServiceAccountToken: false
      imagePullSecrets: [{name: vuoro-ghcr-pull}]
      securityContext: {runAsNonRoot: true, runAsUser: 65532, runAsGroup: 65532, fsGroup: 65532, seccompProfile: {type: RuntimeDefault}}
      containers:
        - name: control
          image: ghcr.io/bayleafwalker/vuoro-cloud@sha256:02b792fdf2324ad56ea3ae7a85e82c348b88ae00894bc2991c678f5b065875bf
          command: [vuoro-control]
          ports: [{name: http, containerPort: 8080}]
          env:
            - {name: VUORO_CLOUD_SERVICE_ROLE, value: control}
            # OAuth AS signing key (D-045/D-046). Required by the validator only
            # once VUORO_CLOUD_OAUTH_CLIENTS_FILE is set (rollout: image, key, clients).
            - {name: VUORO_CLOUD_OAUTH_AS_PRIVATE_KEY_FILE, value: /var/run/vuoro/oauth-as-signing/oauth-as-signing-key.pem}
            - {name: VUORO_CLOUD_OAUTH_AS_PUBLIC_KEY_FILE, value: /var/run/vuoro/oauth-as-verification/oauth-as-public.pem}
            - {name: VUORO_CLOUD_OAUTH_CLIENTS_FILE, value: /var/run/vuoro/oauth-clients/clients.json}
          envFrom: [{secretRef: {name: vuoro-control-runtime}}]
          readinessProbe: {httpGet: {path: /health/ready, port: http}}
          livenessProbe: {httpGet: {path: /health/live, port: http}}
          resources:
            requests: {cpu: 100m, memory: 192Mi}
            limits: {cpu: 500m, memory: 512Mi}
          securityContext:
            allowPrivilegeEscalation: false
            readOnlyRootFilesystem: true
            capabilities: {drop: [ALL]}
          volumeMounts:
            - {name: compatibility, mountPath: /app/config, readOnly: true}
            - {name: signing-key, mountPath: /var/run/vuoro/signing, readOnly: true}
            - {name: verification-key, mountPath: /var/run/vuoro/verification, readOnly: true}
            - {name: oauth-as-signing-key, mountPath: /var/run/vuoro/oauth-as-signing, readOnly: true}
            - {name: oauth-as-verification-key, mountPath: /var/run/vuoro/oauth-as-verification, readOnly: true}
            # Clients file from the vuoro-oauth-clients Secret (credential-rotation.md,
            # "Producing and mounting the real clients file").
            - {name: oauth-clients, mountPath: /var/run/vuoro/oauth-clients, readOnly: true}
      volumes:
        - {name: compatibility, configMap: {name: vuoro-compatibility}}
        - {name: signing-key, secret: {secretName: vuoro-gateway-signing-key}}
        - {name: verification-key, configMap: {name: vuoro-gateway-verification}}
        - {name: oauth-as-signing-key, secret: {secretName: vuoro-oauth-as-signing-key}}
        - {name: oauth-as-verification-key, configMap: {name: vuoro-oauth-as-verification}}
        - {name: oauth-clients, secret: {secretName: vuoro-oauth-clients, optional: true}}
---
apiVersion: v1
kind: Service
metadata: {name: vuoro-control, namespace: vuoro-system, labels: {app.kubernetes.io/name: vuoro-control}}
spec:
  selector: {app.kubernetes.io/name: vuoro-control}
  ports: [{name: http, port: 8080, targetPort: http}]
---
apiVersion: v1
kind: ServiceAccount
metadata: {name: vuoro-control, namespace: vuoro-system}
automountServiceAccountToken: false
